// src/pages/PosRewardCatalogItemPage.tsx
import React, { useState, useEffect, useRef } from 'react';
import {
  IonPage, IonContent, IonList, IonItem, IonLabel, IonToolbar, IonTitle, IonButton,
  IonIcon, IonModal, IonInput, IonSelect, IonSelectOption, IonToggle, IonLoading, IonToast,
