  IonInfiniteScrollContent, IonAlert
} from '@ionic/react';
import { addOutline, createOutline, trashOutline, cashOutline, cubeOutline, checkmarkCircle } from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../components/UserContext';
import {
  PosRewardCatalogItem,
  getAllPosRewardCatalogItems,
  createPosRewardCatalogItem,
  updatePosRewardCatalogItem,
  deletePosRewardCatalogItem
} from '../api/PosRewardCatalogItemApi';
import { useIonViewWillEnter } from '@ionic/react';

// Helper for UTC-7 conversion
const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface FormState {
  name: string;
  rewardType: 'discount' | 'freeProduct' | '';
  requiredPoints: number;
  discountValue?: number;
  freeProductId?: number;
  isActive: boolean;
  description: string;
}

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();
  const [items, setItems] = useState<PosRewardCatalogItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentEditItem, setCurrentEditItem] = useState<PosRewardCatalogItem | null>(null);
  const [formState, setFormState] = useState<FormState>({
    name: '',
    rewardType: '',
    requiredPoints: 0,
    isActive: true,
    description: '',
  });
  const [saving, setSaving] = useState(false);
  const [showAlert, setShowAlert] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<PosRewardCatalogItem | null>(null);

  // Infinite scroll state
  const [displayCount, setDisplayCount] = useState(20);
  const itemsPerPage = 20;

  const loadMoreItems = () => {
    if (displayCount < items.length) {
      setDisplayCount(prevCount => prevCount + itemsPerPage);
    }
  };

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchItems = async () => {
    setLoading(true);
    try {
      const data = await getAllPosRewardCatalogItems(companyId);
      setItems(data);
    } catch (err) {
      setError((err as Error).message ?? 'Error cargando recompensas');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchItems();
  }, [companyId]);

  useEffect(() => {
    if (showModal) {
      if (isEditing && currentEditItem) {
        setFormState({
          name: currentEditItem.name,
          rewardType: currentEditItem.rewardType,
          requiredPoints: currentEditItem.requiredPoints,
          discountValue: currentEditItem.discountValue,
          freeProductId: currentEditItem.freeProductId,
          isActive: currentEditItem.isActive,
          description: currentEditItem.description ?? '',
        });
      } else {
        setFormState({
          name: '',
          rewardType: '',
          requiredPoints: 0,
          isActive: true,
          description: '',
        });
      }
    }
  }, [showModal, isEditing, currentEditItem]);

  const handleSave = async () => {
    setSaving(true);
    setError('');
    try {
      if (isEditing && currentEditItem) {
        await updatePosRewardCatalogItem(currentEditItem.catalogItemId, {
          companyId,
          name: formState.name,
          rewardType: formState.rewardType,
          requiredPoints: formState.requiredPoints,
          discountValue: formState.rewardType === 'discount' ? formState.discountValue : undefined,
          freeProductId: formState.rewardType === 'freeProduct' ? formState.freeProductId : undefined,
          isActive: formState.isActive,
          description: formState.description,
        });
      } else {
        await createPosRewardCatalogItem({
          companyId,
          name: formState.name,
          rewardType: formState.rewardType as 'discount' | 'freeProduct',
          requiredPoints: formState.requiredPoints,
          discountValue: formState.rewardType === 'discount' ? formState.discountValue : undefined,
          freeProductId: formState.rewardType === 'freeProduct' ? formState.freeProductId : undefined,
          isActive: formState.isActive,
          description: formState.description,
        });
      }
      setShowModal(false);
      fetchItems();
    } catch (err) {
      setError((err as Error).message ?? 'Error guardando recompensa');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteConfirm = (item: PosRewardCatalogItem) => {
    setItemToDelete(item);
    setShowAlert(true);
  };

  const handleDelete = async () => {
    if (itemToDelete) {
      setLoading(true);
      setError('');
      try {
        await deletePosRewardCatalogItem(itemToDelete.catalogItemId, companyId);
        fetchItems();
      } catch (err) {
        setError((err as Error).message ?? 'Error eliminando recompensa');
      } finally {
        setLoading(false);
        setItemToDelete(null);
      }
    }
  };

  const handleRewardTypeChange = (e: CustomEvent) => {
    const type = e.detail.value;
    setFormState(prev => ({
      ...prev,
      rewardType: type,
      discountValue: type === 'discount' ? (prev.discountValue ?? 0) : undefined,
      freeProductId: type === 'freeProduct' ? (prev.freeProductId ?? 0) : undefined,
    }));
  };

  const isFormValid = formState.name.trim() !== '' &&
    formState.rewardType !== '' &&
    formState.requiredPoints > 0 &&
    (formState.rewardType === 'discount' ? (formState.discountValue ?? 0) > 0 : true) &&
    (formState.rewardType === 'freeProduct' ? (formState.freeProductId ?? 0) > 0 : true);

  return (
    <IonPage className="posRewardCatalogItem-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Catálogo de Recompensas POS — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonLoading isOpen={loading} message="Cargando recompensas..." />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color="danger"
        />

        <IonListHeader>
          <IonLabel>Recompensas de Lealtad</IonLabel>
          <IonButton onClick={() => { setIsEditing(false); setShowModal(true); }}>
            <IonIcon icon={addOutline} slot="start" />
            Añadir Recompensa
          </IonButton>
        </IonListHeader>

        <IonList className="posRewardCatalogItem-list">
          {items.slice(0, displayCount).map((item) => (
            <IonItem key={item.catalogItemId} className="posRewardCatalogItem-item">
              <IonIcon icon={cubeOutline} slot="start" className="posRewardCatalogItem-icon" />
              <IonLabel>
                <h2>{item.name}</h2>
                <IonText color="medium">
                  <p>Puntos Requeridos: <span className="currency-display">{item.requiredPoints.toFixed(2)}</span></p>
                  <p>Tipo: {item.rewardType === 'discount' ? `Descuento de $${item.discountValue?.toFixed(2)}` : `Producto Gratis (ID: ${item.freeProductId})`}</p>
                </IonText>
                <IonNote slot="end" className={`status-badge status-${item.isActive ? 'active' : 'inactive'}`}>
                  {item.isActive ? 'Activa' : 'Inactiva'}
                </IonNote>
                {item.description && <p><IonText color="medium">{item.description}</IonText></p>}
                <p>
                  <IonText color="medium">Creado: {toHermosillo(item.created_At)}</IonText>
                  {item.updated_at && <IonText color="medium">, Actualizado: {toHermosillo(item.updated_at)}</IonText>}
                </p>
              </IonLabel>
              <IonButton fill="clear" onClick={() => { setIsEditing(true); setCurrentEditItem(item); setShowModal(true); }}>
                <IonIcon icon={createOutline} />
              </IonButton>
              <IonButton fill="clear" color="danger" onClick={() => handleDeleteConfirm(item)}>
                <IonIcon icon={trashOutline} />
              </IonButton>
            </IonItem>
          ))}
          <IonInfiniteScroll onIonInfinite={(ev: CustomEvent<void>) => {
            loadMoreItems();
            (ev.target as HTMLIonInfiniteScrollElement).complete();
          }} disabled={displayCount >= items.length}>
            <IonInfiniteScrollContent loadingText="Cargando más recompensas..." />
          </IonInfiniteScroll>
        </IonList>

        <IonModal isOpen={showModal} onDidDismiss={() => setShowModal(false)}>
          <IonHeader>
            <IonToolbar>
              <IonTitle>{isEditing ? 'Editar Recompensa' : 'Añadir Nueva Recompensa'}</IonTitle>
              <IonButton slot="end" onClick={() => setShowModal(false)}>Cerrar</IonButton>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <div className="posRewardCatalogItem-form-fields">
              <div className="posRewardCatalogItem-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de la Recompensa *"
                  labelPlacement="floating"
                  value={formState.name}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, name: e.detail.value! }))}
                  className={formState.name.trim() === '' ? 'ion-invalid ion-touched' : ''}
                  errorText="El nombre es requerido."
                />
              </div>

              <div className="posRewardCatalogItem-field-group">
                <IonSelect
                  fill="outline"
                  label="Tipo de Recompensa *"
                  labelPlacement="floating"
                  value={formState.rewardType}
                  onIonChange={handleRewardTypeChange}
                  className={formState.rewardType === '' ? 'ion-invalid ion-touched' : ''}
                  errorText="El tipo de recompensa es requerido."
                >
                  <IonSelectOption value="discount">Descuento</IonSelectOption>
                  <IonSelectOption value="freeProduct">Producto Gratis</IonSelectOption>
                </IonSelect>
              </div>

              <div className="posRewardCatalogItem-field-group">
                <IonInput
                  fill="outline"
                  label="Puntos Requeridos *"
                  labelPlacement="floating"
                  type="number"
                  value={formState.requiredPoints}
