                    className={(formState.freeProductId ?? 0) <= 0 ? 'ion-invalid ion-touched' : ''}
                    errorText="El ID del producto es requerido y debe ser mayor a 0."
                  >
                    {(formState.freeProductId ?? 0) > 0 && <IonIcon icon={checkmarkCircle} slot="end" color="success" aria-hidden="true" />}
                  </IonInput>
                </div>
              )}

              <div className="posRewardCatalogItem-field-group ion-padding-top">
